let scene,mode='intro',active=0,clock=0,health=5,weapon=1,auto=false,unlocked={1:true,2:false,3:false},ammo={2:0,3:0},question=null,near=null,checkpoint=135,completed=false;
let jump=false,fireQueued=false,openQueued=false,fireCD=0,noticeUntil=0,shots=[],particles=[],floaters=[],audio,hitStop=0;
function log(type,data={}){events.push({type,active:+active.toFixed(3),...data})}
function sound(f=400,d=.12){try{audio||=new(window.AudioContext||window.webkitAudioContext)();audio.resume();let o=audio.createOscillator(),g=audio.createGain();o.type='triangle';o.frequency.setValueAtTime(f,audio.currentTime);o.frequency.exponentialRampToValueAtTime(f*.5,audio.currentTime+d);g.gain.setValueAtTime(.06,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+d);o.connect(g).connect(audio.destination);o.start();o.stop(audio.currentTime+d)}catch{}}
function burst(x,y,c,count=15){for(let i=0;i<count;i++){let a=Math.random()*Math.PI*2,v=35+Math.random()*145;particles.push({x,y,vx:Math.cos(a)*v,vy:Math.sin(a)*v,life:.3+Math.random()*.55,c})}}
function say(t,seconds=2){$('#notice').textContent=t;noticeUntil=clock+seconds}
function clear(){Object.values(held).forEach(s=>s.clear());jump=fireQueued=openQueued=false}
function hud(){for(let n of[1,2,3]){$('#w'+n).disabled=!unlocked[n];$('#w'+n).classList.toggle('on',weapon===n);$('#w'+n+' small').textContent=n===1?'∞ AMMO':unlocked[n]?ammo[n]+' / '+CAPACITY:'LOCKED';$('#w'+n).classList.toggle('empty',unlocked[n]&&ammo[n]===0)}$('#hearts').textContent='♥'.repeat(health)+'♡'.repeat(5-health);$('#auto small').textContent='AUTO '+(auto?'ON':'OFF');$('#auto').setAttribute('aria-pressed',auto);$('#auto').classList.toggle('on',auto);$('#controls').hidden=mode!=='play';$('#pause').disabled=mode!=='play'&&mode!=='paused';$('#nearby').hidden=mode!=='play'||!near;if(near)$('#drop-name').textContent='×'+near.n+' · '+(unlocked[near.n]?'REFILL AMMO':'POWER BOOST');}
function select(n){if(mode==='play'&&unlocked[n]){weapon=n;sound(300+n*100);hud();log('weapon',{weapon:n})}}
function pause(){if(mode==='play'){mode='paused';clear();$('#paused').hidden=false;log('pause')}else if(mode==='paused'){mode='play';$('#paused').hidden=true;log('resume')}hud()}
function fact(d){return [4,7,2,9,5,10,3,8,6,1][(d.attempt+(d.n===3?2:0))%10]}
function openDrop(d){if(mode!=='play'||d.status!=='ready'||Math.abs(p.x-d.x)>145)return;question={drop:d,n:d.n,value:fact(d)};mode='question';clear();$('#question').hidden=false;$('#reward').textContent=(unlocked[d.n]?'REFILL':'UNLOCK')+' ×'+d.n+' · '+CAPACITY+' ROUNDS';$('#equation').textContent=d.n+' × '+question.value+' = ?';let correct=d.n*question.value,values=[correct,correct+d.n,correct> d.n?correct-d.n:correct+1];for(let i=values.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[values[i],values[j]]=[values[j],values[i]]}$('#answers').replaceChildren();for(let v of values){let b=document.createElement('button');b.textContent=v;b.onclick=()=>answer(v);$('#answers').append(b)}sound(780,.16);hud();log('question',{factor:d.n,value:question.value,attempt:d.attempt})}
